mkdir -p /tmp/indep && cat > /tmp/indep/check.py <<'EOF'
import sys, math, pandas as pd
from datetime import timedelta as td
from zoneinfo import ZoneInfo
Z=ZoneInfo('America/Chicago'); week=sys.argv[1]; sched_path=sys.argv[2]
ex=pd.read_csv(f'/app/data/northwind/export_{week}.csv')
ex['t']=pd.to_datetime(ex.interval_start_local+ex.utc_offset,format='%Y-%m-%d %H:%M%z',utc=True)
def sl(a,n,aht,T):
    if a<=0: return 1.0
    if n<=a: return 0.0
    s=sum(a**k/math.factorial(k) for k in range(n)); top=a**n/math.factorial(n)*n/(n-a)
    return 1-top/(s+top)*math.exp(-(n-a)*T/aht)
TG={'priority':(0.9,30),'standard':(0.8,20),'vip':(0.9,20)}
def req(v,aht,q):
    a=v*aht/1800
    if a<=0: return 0
    n=1
    while not (sl(a,n,aht,TG[q][1])>=TG[q][0] and a/n<=0.85): n+=1
    return n
ex['req']=[req(v,a,q) for v,a,q in zip(ex.volume,ex.aht_sec,ex.queue)]
R={(q,t):r for q,t,r in zip(ex.queue,ex.t,ex.req)}
grid=sorted(ex.t.unique())
s=pd.read_csv(sched_path); ag=pd.read_csv('/app/data/agents/northwind.csv').set_index('agent_id')
for c in ['segment_start_utc','segment_end_utc','break_start_utc']: s[c]=pd.to_datetime(s[c],utc=True)
s['day']=s.segment_start_utc.dt.tz_convert(Z).dt.date
gross={}; net={}
for r in s.itertuples():
    for t in grid:
        if r.segment_start_utc<=t<r.segment_end_utc:
            gross[(r.queue,t)]=gross.get((r.queue,t),0)+1
            onb = r.break_minutes>0 and r.break_start_utc < t+td(minutes=30) and t < r.break_start_utc+td(minutes=int(r.break_minutes))
            net[(r.queue,t)]=net.get((r.queue,t),0)+(0 if onb else 1)
v={}
def bad(k): v[k]=v.get(k,0)+1
TPL={'E8':[(6,14)],'D8':[(9,17)],'L8':[(13,21)],'N8':[(16,24)],'P6a':[(7,13)],'P6b':[(15,21)],'P4':[(10,14)],'S44':[(8,12),(16,20)]}
spans=[]
for (aid,day),g in s.groupby(['agent_id','day']):
    g=g.sort_values('segment_start_utc'); con=ag.loc[aid,'contract']; sk=set(ag.loc[aid,'skills'].split(';'))
    if g.template_id.nunique()!=1 or g.queue.nunique()!=1: bad('multi_shift_day')
    tid=g.template_id.iloc[0]; q=g.queue.iloc[0]
    loc=[(a.tz_convert(Z).hour, (b.tz_convert(Z).hour or 24) if b.tz_convert(Z).date()==day else 24) for a,b in zip(g.segment_start_utc,g.segment_end_utc)]
    if loc!=[tuple(x) for x in TPL[tid]]: bad('template')
    if len(g)>1 and con!='PT': bad('split_FT')
    if q not in sk: bad('skill')
    hrs=((g.segment_end_utc-g.segment_start_utc).dt.total_seconds()/3600).sum()
    st=g.segment_start_utc.min(); spans.append((aid,st,g.segment_end_utc.max(),hrs,day))
    b=g[g.break_minutes>0]
    if hrs>=6:
        if len(b)!=1 or b.break_minutes.iloc[0]!=20: bad('break_count'); continue
        bs=b.break_start_utc.iloc[0]; off=(bs-st).total_seconds()/3600
        if not (2<=off<=5): bad('break_window')
        win=[t for t in grid if st+td(hours=2)<=t<=st+td(hours=5) and any(x<=t and t+td(minutes=20)<=y for x,y in zip(g.segment_start_utc,g.segment_end_utc))]
        sur={t:gross.get((q,t),0)-R[(q,t)] for t in win}
        slot=[t for t in win if t<=bs<t+td(minutes=30)]
        if not slot or sur[slot[0]]<max(sur.values()): bad('break_surplus')
        if off==5: bad('(info) break_at_5h')
    elif len(b): bad('break_on_short')
sp=pd.DataFrame(spans,columns=['aid','st','en','h','day'])
for aid,g in sp.groupby('aid'):
    g=g.sort_values('st'); con=ag.loc[aid,'contract']
    if g.h.sum()>(40 if con=='FT' else 24)+1e-9: bad('weekly_hours')
    if ((g.st.shift(-1)-g.en).dropna()<td(hours=11)).any(): bad('rest')
    if ((g.st.shift(-1)-g.en).dropna()<td(0)).any(): bad('overlap')
    days=sorted(g.day); run=1
    for a,b2 in zip(days,days[1:]):
        run=run+1 if (b2-a).days==1 else 1
        if run>5: bad('consec'); break
for t in grid:
    lh=t.tz_convert(Z); h=lh.hour+lh.minute/60
    if 6<=h<24 and net.get(('vip',t),0)<1: bad('vip_floor_net')
    if 6<=h<24 and gross.get(('vip',t),0)<1: bad('vip_floor_gross')
att={}
for q,(lo,hi) in {'priority':(6,24),'standard':(6,24),'vip':(8,20)}.items():
    ops=[t for t in grid if lo<=t.tz_convert(Z).hour+t.tz_convert(Z).minute/60<hi]
    att[q]=round(sum(net.get((q,t),0)>=R[(q,t)] for t in ops)/len(ops),3)
H=((s.segment_end_utc-s.segment_start_utc).dt.total_seconds()/3600).sum(); RH=ex.req.sum()*0.5
und=sum(max(0,R[(q,t)]-net.get((q,t),0))*0.5 for (q,t) in R)
print(week,'intervals',len(grid),'att',att,'sched',H,'req',RH,'ratio',round(H/RH,3),'under',und,'agents',s.agent_id.nunique(),'violations',v)
EOF
cd /tmp && for w in 2026-W42 2026-W43; do python -I /tmp/indep/check.py $w /tmp/sched_$w.csv; done; python -I /tmp/indep/check.py 2026-W44 /app/out/northwind/schedule.csv

